const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const boston = ee.Geometry.Point([-71.0589, 42.3601]); // Boston, MA coordinates
    const startDate = '2019-01-29';
    const endDate = '2019-02-05'; // The period includes Feb 5.

    // 2. Data Acquisition
    let era5 = ee.ImageCollection('ECMWF/ERA5/DAILY')
      .filterDate(startDate, ee.Date(endDate).advance(1, 'day')) // Filter to include endDate
      .filterBounds(boston)
      .select('mean_2m_air_temperature');

    const collectionSize = await era5.size().getInfo();

    if (collectionSize === 0) {
      console.log("No ERA5 daily data found for the specified date range and location.");
      console.log("C1");
      return;
    }

    // Convert Kelvin to Celsius: K - 273.15
    const dailyTemperaturesC = await era5.map(image =>
      image.subtract(273.15).rename('temperature_celsius')
    );

    // Get a list of daily temperatures at the Boston point
    const temperatureList = await dailyTemperaturesC
      .getRegion(boston, 1000) // Scale is less critical for a point, but good practice
      .slice(1) // Remove header row
      .map(row => ee.List(row).get(3)) // Get the temperature_celsius value
      .getInfo();

    // Remove any null values from the list (though unlikely with ERA5 point data)
    const validTemperatures = temperatureList.filter(temp => temp !== null && typeof temp === 'number');

    if (validTemperatures.length === 0) {
      console.log("Images exist, but no valid temperature pixels found at the point.");
      console.log("C2");
      return;
    }

    // 3. Calculation
    const maxTempC = Math.max(...validTemperatures);
    const minTempC = Math.min(...validTemperatures);

    if (maxTempC === null || minTempC === null || isNaN(maxTempC) || isNaN(minTempC)) {
      console.log("Calculation of max/min temperature resulted in invalid values.");
      console.log("C3");
      return;
    }

    const tempDifference = maxTempC - minTempC;

    // 4. Validation & Final Answer
    console.log(`Period: ${startDate} to ${endDate}`);
    console.log(`Total images processed: ${collectionSize}`);
    console.log(`Daily temperatures (C): ${validTemperatures.map(t => t.toFixed(2)).join(', ')}`);
    console.log(`Max daily temp (C): ${maxTempC.toFixed(2)}`);
    console.log(`Min daily temp (C): ${minTempC.toFixed(2)}`);
    console.log(`Temperature difference (C): ${tempDifference.toFixed(2)}`);

    const threshold = 22;

    if (tempDifference >= threshold) {
      console.log("A"); // Yes
    } else {
      console.log("B"); // No
    }

  } catch (error) {
    console.log("An error occurred during analysis: ", error);
    console.log("D"); // General error
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
